// Que faire à ce passage ? n8n passe toutes les 30 minutes, de 7 h 15 à 22 h 45, quand le Mac est allumé.
// Rien n'a d'heure fixe : chaque tâche part au premier passage après son heure, et une seule fois.
// - La collecte : au plus toutes les 4 heures (réglable), et juste avant une préparation.
// - Les pages sans flux : une fois par jour, avec la première collecte du jour.
// - La préparation de la semaine : au premier passage à partir du lundi 6 h (réglable), une fois par
//   semaine ; Mac éteint le lundi, elle part au premier réveil suivant, jusqu'au dimanche.
// - Le rappel doux : au premier passage à partir du jeudi 16 h 30 (réglable), si la préparation de la
//   semaine est partie avant cette heure ; jusqu'au dimanche (ergonomie.md, F1 et F2).
// - La synthèse du mois s'écrit à la dernière séance du mois, celle du dernier mercredi (DISPOSITIF.md, section 2) :
//   la semaine de ce mercredi porte le mois (semaine.synthese, AAAA-MM), et sa préparation en donne la matière.
// Les réglages viennent du nœud Réglages (variables d'environnement, avec des valeurs par défaut).
// En mode essai (build_parlia.py --test), tout est dû. Rien n'est enregistré ici, sauf sd._passage,
// le carnet du passage en cours, que lit le message de #status.
const sd = $getWorkflowStaticData('global');
const r = $input.first().json || {};
const entier = (v, defaut, min, max) => {
  const n = parseInt(v, 10);
  return Number.isFinite(n) && n >= min && n <= max ? n : defaut;
};
const heureMinute = (v, defaut) => {
  const m = /^(\d{1,2})\s*(?:[:h]\s*(\d{2})?)?$/i.exec(String(v == null ? '' : v).trim());
  if (!m) return defaut;
  const h = Number(m[1]);
  const mn = Number(m[2] || 0);
  return h <= 23 && mn <= 59 ? { h, mn } : defaut;
};
const reglages = {
  prepJour: entier(r.prepJour, 1, 1, 7),
  prepHeure: heureMinute(r.prepHeure, { h: 6, mn: 0 }),
  rappelJour: entier(r.rappelJour, 4, 1, 7),
  rappelHeure: heureMinute(r.rappelHeure, { h: 16, mn: 30 }),
  collecteHeures: entier(r.collecteHeures, 4, 1, 24),
  // Le nombre maximal de fiches ; aucun minimum (sources.md, 6.2, règle 3).
  candidatsMax: entier(r.candidatsMax, 8, 1, 30),
  forum: String(r.forum) === '1',
  discord: String(r.discord) === '1',
  statut: String(r.statut) === '1',
  mention: /^\d{5,25}$/.test(String(r.mention || '')) ? String(r.mention) : '',
  essai: String(r.essai) === '1',
  // Le modèle qui résume les originaux (build_parlia.py) : la préparation le nomme.
  modeleResumes: String(r.modeleResumes || '').slice(0, 100),
};

const lundi = $now.startOf('week');
const mercredi = lundi.plus({ days: 2 });
const semaine = {
  cle: $now.toFormat("kkkk-'S'WW"),
  numero: $now.weekNumber,
  lundi: lundi.toISODate(),
  dimanche: lundi.plus({ days: 6 }).toISODate(),
  mercredi: mercredi.toISODate(),
  synthese: mercredi.plus({ weeks: 1 }).month !== mercredi.month ? mercredi.toFormat('yyyy-MM') : '',
};
const moment = (jour, hm) => lundi.plus({ days: jour - 1 }).set({ hour: hm.h, minute: hm.mn, second: 0, millisecond: 0 });
const maintenant = $now.toMillis();
const prep = sd.prep || {};

const seuilPrep = moment(reglages.prepJour, reglages.prepHeure);
const preparation = reglages.essai || ($now >= seuilPrep && prep.semaine !== semaine.cle);
const seuilRappel = moment(reglages.rappelJour, reglages.rappelHeure);
const rappel = reglages.essai || ($now >= seuilRappel && prep.semaine === semaine.cle && !prep.rappel
  && (Number(prep.at) || 0) < seuilRappel.toMillis());

const derniere = Number(sd.lastCollectAt) || 0;
const marge = 10 * 60 * 1000; // le pas de 30 minutes
const collecte = reglages.essai
  || maintenant - derniere >= reglages.collecteHeures * 3600 * 1000 - marge
  || (preparation && maintenant - derniere > 30 * 60 * 1000);
const pages = collecte && (reglages.essai || sd.pagesJour !== $now.toISODate());

if (!collecte && !preparation && !rappel) return [];
sd._passage = {
  debut: maintenant,
  collecte, pages, preparation, rappel,
  essai: reglages.essai,
  sommeilH: derniere ? Math.round((maintenant - derniere) / 360000) / 10 : null,
};
return [{ json: { collecte, pages, jorf: collecte, preparation, rappel, essai: reglages.essai, semaine, reglages } }];

// Les sources de la veille ParlIA lues par flux RSS ou Atom, d'après le rapport des sources du 29 octobre 2026
// (sources.md, section 4.1 : les sources « à retenir »). Les pages sans flux, le catalogue d'OpenRouter, la fiche
// data.gouv.fr et les comptes Hugging Face sont lus par collecte-pages-api.js ; le Journal officiel, par
// jorf-parlia.js. Ce nœud ne renvoie rien quand la collecte n'est pas due : la branche s'arrête là.
// id : repère du rapport · s : nom · u : adresse finale (après redirection) · axe : l'axe du thème
// nature : editeur | institution | auteurs | praticien | agregateur · primaire : la source produit l'information
// filtre : mots exigés dans le titre ou l'extrait, sinon l'article est écarté avant le tri
// cnil : la règle « toujours un texte de la CNIL ou du CEPD » · decision : source des modèles de décision
// arxiv : prépublication (au plus 3 candidats par semaine) · role : 'detecteur' = jamais trié (remaniement)
// reecrire : [ancien hôte, nouvel hôte] pour les liens cassés de data.senat.fr
if (!$('Que faire ?').first().json.collecte) return [];
const IA_UE = '\\b(ai|a\\.i\\.|artificial intelligence|ai act|ai office|general-purpose|gpai|llms?|language models?|automated decision\\w*|algorithm\\w*)\\b';
const ARXIV = 'https://export.arxiv.org/api/query?search_query=';
const FLUX = [
  // ---- Fournisseurs et coûts ----
  { id: 'A01', s: "OpenRouter, journal de l'API", u: 'https://openrouter.ai/docs/changelog/rss.xml', axe: 'fournisseurs', nature: 'editeur', primaire: true },
  { id: 'A03', s: 'OpenAI, actualités', u: 'https://openai.com/news/rss.xml', axe: 'fournisseurs', nature: 'editeur', primaire: true,
    filtre: '\\b(api|pricing|prices?|deprecat\\w*|retir\\w*|decisions?|gpt-[\\w.]+|luna|terra|batch|developers?|residency|europe|eu|classif\\w*)\\b' },
  { id: 'A04', s: 'Anthropic, notes de version', u: 'https://platform.claude.com/docs/en/release-notes/feed.xml', axe: 'fournisseurs', nature: 'editeur', primaire: true },
  { id: 'A05', s: 'Mistral AI, actualités', u: 'https://mistral.ai/news/rss', axe: 'fournisseurs', nature: 'editeur', primaire: true },
  { id: 'F15', s: 'Google, blog « Developer tools »', u: 'https://blog.google/innovation-and-ai/technology/developers-tools/rss/', axe: 'fournisseurs', nature: 'editeur', primaire: true },
  { id: 'A07', s: 'Simon Willison, étiquette « llms »', u: 'https://simonwillison.net/tags/llms.atom', axe: 'fournisseurs', nature: 'praticien', primaire: false,
    filtre: '(pric\\w*|cost|cheap|classif\\w*|eval\\w*|structured|decision|deprecat\\w*|retir\\w*|batch|logprob\\w*|calibrat\\w*)' },
  // ---- Modèles de décision ----
  { id: 'X01', s: 'Cloudflare, journal de Workers AI', u: 'https://developers.cloudflare.com/changelog/rss/workers-ai.xml', axe: 'fournisseurs', nature: 'editeur', primaire: true, decision: true },
  { id: 'R2', s: 'arXiv : modèles de décision et calibration', axe: 'qualite', nature: 'auteurs', primaire: true, arxiv: true,
    u: ARXIV + 'ti:%22decision+model%22+OR+ti:%22decision+models%22+OR+ti:jev+OR+ti:%22system+one%22+OR+%28ti:calibration+AND+%28ti:LLM+OR+ti:LLMs+OR+ti:classification+OR+ti:classifiers%29%29&sortBy=submittedDate&sortOrder=descending&max_results=50' },
  // ---- Qualité de l'étiquetage ----
  { id: 'R1', s: 'arXiv : étiquetage par modèle de langage', axe: 'qualite', nature: 'auteurs', primaire: true, arxiv: true,
    u: ARXIV + '%28ti:annotation+OR+ti:annotator+OR+ti:annotators+OR+ti:labeling+OR+ti:labelling+OR+ti:labels%29+AND+%28abs:LLM+OR+abs:LLMs+OR+abs:%22language+model%22+OR+abs:%22language+models%22%29&sortBy=submittedDate&sortOrder=descending&max_results=50' },
  { id: 'R3', s: 'arXiv : textes parlementaires ou administratifs', axe: 'qualite', nature: 'auteurs', primaire: true, arxiv: true,
    u: ARXIV + '%28abs:parliamentary+OR+abs:%22written+questions%22+OR+abs:%22policy+topics%22+OR+abs:%22comparative+agendas%22+OR+abs:%22public+administration%22%29+AND+%28abs:classification+OR+abs:annotation+OR+abs:labeling%29&sortBy=submittedDate&sortOrder=descending&max_results=50' },
  { id: 'A14', s: 'Hamel Husain', u: 'https://hamel.dev/index.xml', axe: 'qualite', nature: 'praticien', primaire: true },
  { id: 'A13', s: 'Hugging Face, blog', u: 'https://huggingface.co/blog/feed.xml', axe: 'qualite', nature: 'editeur', primaire: true,
    filtre: '(eval\\w*|annotat\\w*|label\\w*|classif\\w*|calibrat\\w*|judge|benchmark|decision|argilla|setfit|zero-shot)' },
  // ---- Conformité ----
  { id: 'A08', s: 'CNIL, actualités', u: 'https://www.cnil.fr/fr/rss.xml', axe: 'conformite', nature: 'institution', primaire: true, cnil: true },
  // Le flux anglais du CEPD (feed/news_en) répond « Sorry » (erreur 503) depuis la mise en service du bot ; le flux
  // français donne les mêmes actualités, aux titres en français ou en anglais (vérifié le 16 novembre 2026).
  { id: 'A09', s: 'CEPD, actualités', u: 'https://www.edpb.europa.eu/feed/news_fr', axe: 'conformite', nature: 'institution', primaire: true, cnil: true },
  { id: 'A10', s: 'Commission européenne, numérique', u: 'https://digital-strategy.ec.europa.eu/en/rss.xml', axe: 'conformite', nature: 'institution', primaire: true, filtre: IA_UE },
  { id: 'Z01', s: 'Sénat, dossier de la loi DDADUE', u: 'https://www.senat.fr/dossier-legislatif/rss/doslegpjl25-118.xml', axe: 'conformite', nature: 'institution', primaire: true },
  // ---- Exploitation ----
  { id: 'X06', s: 'data.senat.fr, actualités', u: 'https://data.senat.fr/feed/actualites-atom.xml', axe: 'exploitation', nature: 'institution', primaire: true,
    reecrire: ['data-ab.senat.fr', 'data.senat.fr'] },
  // Détecteur de secours du remaniement, à l'essai : jamais trié, seulement filtré sur le titre (normaliser-parlia.js).
  { id: 'X11', s: 'Élysée, communiqués', u: 'https://www.elysee.fr/feed', axe: 'exploitation', nature: 'institution', primaire: true, role: 'detecteur' },
];
return FLUX.map((f) => ({ json: f }));

// ---- Outils communs de la veille ParlIA (workflows/src-parlia/outils.js) ----
// build_parlia.py place ce fichier en tête de chaque nœud Code : n8n ne permet pas d'importer un module.
const PARLIA = {
  AXES: ['fournisseurs', 'qualite', 'conformite', 'exploitation'],
  NOM_AXE: {
    fournisseurs: 'Fournisseurs et coûts', qualite: "Qualité de l'étiquetage", conformite: 'Conformité',
    exploitation: 'Exploitation', hors_theme: 'Hors thème',
  },
  NATURES: ['editeur', 'institution', 'auteurs', 'praticien', 'presse', 'agregateur', 'inconnu'],
  NOM_NATURE: {
    editeur: 'éditeur', institution: 'institution', auteurs: 'auteurs', praticien: 'praticien', presse: 'presse',
    agregateur: 'agrégateur', inconnu: 'nature inconnue',
  },
  THEME: "« Étiqueter les questions écrites du Sénat avec un modèle de langage commercial : choisir, mesurer et pouvoir remplacer le fournisseur, dans le respect du RGPD et du règlement européen sur l'IA. »",
  // Les modèles suivis (sources.md, 4.4) : leurs changements de prix et leurs retraits sont toujours proposés.
  // Mistral Large 4 depuis le 16 novembre 2026 : un candidat possible du comparatif (séances 02 et 03).
  SUIVI: [
    'openai/gpt-6-luna', 'anthropic/claude-haiku-5.5', 'mistralai/mistral-small-3.2-24b-instruct',
    'openai/gpt-4o-mini', 'openai/gpt-6.1-terra', 'google/gemini-4-argon', 'mistralai/mistral-large-4-0',
  ],
  // Les mêmes, et les modèles de décision, tels qu'on les reconnaît dans un titre ou un extrait ; Kev et Zuse depuis
  // le 16 novembre 2026 (séance 03). L'institut Zuse de Berlin n'est pas le modèle de Bineric.
  NOMS_SUIVIS: /\b(gpt-6-luna|gpt-6 luna|decisions api|claude haiku 5\.5|claude-haiku-5\.5|mistral small 3\.2|mistral-small-3\.2|gpt-4o mini|gpt-4o-mini|gpt-6\.1[- ]terra|gemini 4 argon|gemini-4-argon|mistral large 4|mistral-large-4|jev|kev|clef|clef-flash|zuse(?![- ]institut)|d1|d1-ultra|decider)\b/i,
  // L'état du projet, écrit sans date : le seul bloc à mettre à jour quand le projet avance (le comparatif commencé,
  // un service choisi…). Il entre dans la consigne du tri (consigne-tri-parlia.js) et dans la demande de résumé des
  // originaux (originaux-parlia.js) : changer alors leur version (VERSION, VERSION_RESUME).
  ETAT_DU_PROJET: `- ParlIA propose les trois ministères les plus probables pour une question écrite de sénateur, à partir du titre et du texte de la question (données publiques du Sénat). Ces propositions viennent du modèle que Louis entraîne lui-même : l'application n'utilise aucun service d'IA du marché.
- Une étape à venir : un service d'IA du marché, modèle de langage ou modèle de décision, pourrait étiqueter, hors ligne, les questions sans réponse publiée, en choisissant un ministère dans une liste fermée, avec un score de confiance ; une personne validerait chaque proposition. Le comparatif qui choisira ce service n'a pas commencé : aucun service n'est choisi.
- Les candidats à l'étude pour ce comparatif, dont aucun n'est utilisé : la Decisions API d'OpenAI (GPT-6 Luna), Jev de TypeSafe AI, Kev (une reproduction ouverte de Jev), Clef de Cloudflare, Zuse de Bineric et d1 de Liquid AI, qui sont des modèles de décision, et les modèles de langage de la liste de suivi, dont Mistral Large 4.
- Le protocole prévu pour le comparatif : mesurer d'abord l'accord du service avec 3 267 questions dont le ministère est connu ; consigner la version du modèle et la date de chaque appel ; garder la réponse brute ; ne jamais mettre une étiquette du service dans le jeu de test ; garder l'étiquetage assisté seulement s'il améliore le macro-F1.
- L'épreuve E5 porte sur un remaniement du Gouvernement qui change la liste des ministères. La soutenance a lieu en janvier 2027.`,
  UA: 'veille-parlia/1.0 (veille de certification de Louis; +https://github.com/lougail)',
  // Les retraits d'OpenAI (sa page des retraits, F02), de Cloudflare (les billets de retraits du journal de Workers
  // AI, X01) et de Google (la page des retraits de Gemini, F13, depuis le 16 novembre 2026) : le bot n'en garde que
  // les lignes des modèles de texte (ligneHorsTexte). Le 5 novembre 2026, Cloudflare arrêtait seize modèles de texte
  // et huit autres (son, image, vision, plongements) ; les pages d'OpenAI et de Google mêlent aux modèles de texte
  // ceux d'image, de son, de vidéo, de musique, de plongements, de modération ou de robotique.
  RETRAITS_TEXTE: ['F02', 'X01', 'F13'],
};

// Texte lisible : sans balises ni entités, espaces réduits.
function texteSimple(s) {
  return String(s == null ? '' : s)
    .replace(/<[^>]*>/g, ' ')
    .replace(/&nbsp;|&#160;/gi, ' ').replace(/&amp;/gi, '&').replace(/&lt;/gi, '<').replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"').replace(/&#39;|&#x27;|&rsquo;|&lsquo;/gi, "'").replace(/&laquo;/gi, '«').replace(/&raquo;/gi, '»')
    .replace(/&[a-z]+;|&#\d+;/gi, ' ')
    .replace(/\s+/g, ' ').trim();
}
function tronquer(s, n) {
  const t = String(s == null ? '' : s);
  if (t.length <= n) return t;
  const coupe = t.lastIndexOf(' ', n - 1);
  return t.slice(0, coupe > n * 0.6 ? coupe : n - 1).trim() + '…';
}
// Empreinte courte et stable (djb2), pour reconnaître un texte déjà vu sans le garder.
function hacher(s) {
  let h = 5381;
  const t = String(s);
  for (let i = 0; i < t.length; i++) h = ((h << 5) + h + t.charCodeAt(i)) >>> 0;
  return h.toString(36);
}
// Le domaine d'une adresse ; new URL() n'existe pas dans le bac à sable de n8n.
function domaineDe(url) {
  const m = /^https?:\/\/([^/?#:]+)/i.exec(String(url || ''));
  return m ? m[1].toLowerCase().replace(/^www\./, '') : '';
}
// La clé d'une adresse, pour le dédoublonnage : sans protocole, sans www, sans paramètres de suivi. Pour une étude
// d'arXiv, sans son numéro de version : arxiv.org/abs/2611.15592v2 est la même étude que …v1 (18 novembre 2026).
function cleAdresse(url) {
  const m = /^https?:\/\/([^/?#]+)([^?#]*)(\?[^#]*)?/i.exec(String(url || '').trim());
  if (!m) return '';
  const hote = m[1].toLowerCase().replace(/^(www|m)\./, '');
  let chemin = m[2].replace(/\/+$/, '');
  if (hote === 'arxiv.org' && /^\/abs\//i.test(chemin)) chemin = chemin.replace(/v\d+$/i, '');
  let requete = '';
  if (m[3]) {
    const garde = m[3].slice(1).split('&').filter((p) => p && !/^(utm_|ref=|fbclid|gclid)/i.test(p)).sort();
    if (garde.length) requete = '?' + garde.join('&');
  }
  return hote + chemin + requete;
}
// Une cellule de tableau Markdown : ni barre verticale ni retour à la ligne.
function cellule(s) {
  return String(s == null ? '' : s).replace(/\|/g, '\\|').replace(/\s*\n\s*/g, ' ').trim();
}
// Un texte pour Discord : mentions collectives neutralisées.
function pourDiscord(s) {
  return String(s == null ? '' : s).replace(/@(everyone|here)/gi, '@\u200b$1');
}
// Une date ISO (AAAA-MM-JJ) en toutes lettres : « 4 novembre 2026 », « 1er décembre 2026 ».
const MOIS_FR = ['janvier', 'février', 'mars', 'avril', 'mai', 'juin', 'juillet', 'août', 'septembre', 'octobre', 'novembre', 'décembre'];
function dateLongue(iso) {
  const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(String(iso || ''));
  if (!m) return '';
  return Number(m[3]) + (m[3] === '01' ? 'er' : '') + ' ' + MOIS_FR[Number(m[2]) - 1] + ' ' + m[1];
}
// Les dates écrites dans un texte (pages sans flux), dans l'ordre : 2026-10-14, October 14, 2026, 14 octobre 2026,
// ou 10.22.2026 (mois.jour.année, chez Liquid AI). Renvoie une liste de AAAA-MM-JJ.
// Une date collée à un nom (« gpt-image-2-2026-04-21 », une version datée) n'est pas une date.
const MOIS_EN = { jan: 1, feb: 2, mar: 3, apr: 4, may: 5, jun: 6, jul: 7, aug: 8, sep: 9, sept: 9, oct: 10, nov: 11, dec: 12 };
function datesDansTexte(texte) {
  const t = String(texte || '');
  const deux = (n) => String(n).padStart(2, '0');
  const candidats = [];
  for (const m of t.matchAll(/(?<![\w-])(20\d{2})-(\d{2})-(\d{2})(?=T\d|[^\w-]|$)/g)) {
    if (Number(m[2]) <= 12 && Number(m[3]) <= 31) candidats.push({ i: m.index, d: m[1] + '-' + m[2] + '-' + m[3] });
  }
  for (const m of t.matchAll(/\b(jan|feb|mar|apr|may|jun|jul|aug|sept?|oct|nov|dec)[a-z]*\.?\s+(\d{1,2}),?\s+(20\d{2})\b/gi)) {
    candidats.push({ i: m.index, d: m[3] + '-' + deux(MOIS_EN[m[1].toLowerCase()]) + '-' + deux(m[2]) });
  }
  for (const m of t.matchAll(/\b(\d{1,2})(?:er)?\s+(janvier|février|fevrier|mars|avril|mai|juin|juillet|août|aout|septembre|octobre|novembre|décembre|decembre)\s+(20\d{2})\b/gi)) {
    const mois = m[2].toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
    const n = ['janvier', 'fevrier', 'mars', 'avril', 'mai', 'juin', 'juillet', 'aout', 'septembre', 'octobre', 'novembre', 'decembre'].indexOf(mois) + 1;
    if (n) candidats.push({ i: m.index, d: m[3] + '-' + deux(n) + '-' + deux(m[1]) });
  }
  for (const m of t.matchAll(/\b(\d{1,2})\.(\d{1,2})\.(20\d{2})\b/g)) {
    if (Number(m[1]) <= 12 && Number(m[2]) <= 31) candidats.push({ i: m.index, d: m[3] + '-' + deux(m[1]) + '-' + deux(m[2]) });
  }
  candidats.sort((a, b) => a.i - b.i);
  return candidats.map((c) => c.d);
}
// La première date écrite dans un texte, ou une chaîne vide.
function dateDansTexte(texte) {
  return datesDansTexte(texte)[0] || '';
}
// ---- Les modèles de texte, sur les pages de retraits (PARLIA.RETRAITS_TEXTE) ----
// Un modèle d'image, de son, de vidéo, de plongements (embeddings) ou de modération se reconnaît à son nom : chez
// OpenAI gpt-image-1-mini, chatgpt-image-latest, dall-e-3, tts-1, whisper-1, gpt-realtime, gpt-4o-mini-transcribe,
// sora-2, text-embedding-3-small, omni-moderation ; chez Cloudflare melotts, stable-diffusion, dreamshaper, flux,
// llava, embeddinggemma, deepgram/aura, deepgram/nova ; chez Google gemini-3-pro-image, imagen, nano-banana (images),
// veo (vidéo), lyria (musique), gemini-3.8-live (voix), gemini-robotics.
// « tts » et « voice » ne comptent pas au milieu d'un mot : ni mattshumer, ni invoice.
const MODELES_HORS_TEXTE = /image|dall-?e|flux|stable-diffusion|sdxl|dreamshaper|inpaint|banana|(?<![a-z])veo-\d|lyria|robotics|(?<![a-z])live(?![a-z])|(?<![a-z])tts|tts(?![a-z])|whisper|transcri|audio|realtime|speech|(?<![a-z])voice|sora|video|embedding|similarity|search-(ada|babbage|curie|davinci)|rerank|moderation|llama-guard|llava|resnet|detr|uform|deepgram\/|^aura\b|^nova-\d/i;
