    if (n === 0) return 0;
    besoin(n);
    const v = tampon & ((1 << n) - 1);
    tampon >>>= n;
    nb -= n;
    return v;
  };
  const symbole = (h) => {
    while (nb < h.max && pos < src.length) {
      tampon |= src[pos++] << nb;
      nb += 8;
    }
    const e = h.t[tampon & ((1 << h.max) - 1)];
    const l = e & 15;
    if (e < 0 || l > nb) throw new Error('code de Huffman invalide');
    tampon >>>= l;
    nb -= l;
    return e >> 4;
  };
