    if (o + n <= out.length) return;
    if (o + n > 400 * 1024 * 1024) throw new Error('archive trop grosse');
    const plus = new Uint8Array(Math.max(out.length * 2, o + n));
    plus.set(out.subarray(0, o));
    out = plus;
