      tampon >>>= nb & 7;
      nb -= nb & 7;
      const len = bits(16);
      const nlen = bits(16);
      if ((len ^ 0xffff) !== nlen) throw new Error('bloc stocké invalide');
      pos -= nb >> 3;
      tampon = 0;
      nb = 0;
      if (pos + len > src.length) throw new Error('archive tronquée');
      place(len);
      out.set(src.subarray(pos, pos + len), o);
      o += len;
      pos += len;
      continue;
    }
    let hl;
    let hd;
    if (type === 1) {
      if (!fixeL) {
