  if (x && typeof x === 'object' && typeof x.byteLength === 'number') return new Uint8Array(x);
  if (x && x.type === 'Buffer' && Array.isArray(x.data)) return Uint8Array.from(x.data);
  if (x && x.body !== undefined) return enOctets(x.body);
